from copy import deepcopy

# Count colors in each quadrant
def count_colors_quadrants(grid):
    h, w = len(grid), len(grid[0])
    quad = {'TL': {}, 'TR': {}, 'BL': {}, 'BR': {}}
    for c in set(flatten(grid)):
        if c == 0: continue
        for r in range(h):
            for co in range(w):
                if grid[r][co] == c:
                    if r < h//2 and co < w//2:
                        quad['TL'][c] = quad['TL'].get(c, 0) + 1
                    elif r < h//2 and co >= w//2:
                        quad['TR'][c] = quad['TR'].get(c, 0) + 1
                    elif r >= h//2 and co < w//2:
                        quad['BL'][c] = quad['BL'].get(c, 0) + 1
                    else:
                        quad['BR'][c] = quad['BR'].get(c, 0) + 1
    return quad

def flatten(g):
    res = []
    for row in g:
        for x in row:
            res.append(x)
    return res

