print("\n=== Centroids (row, col) ===")
def compute_centroids(grid):
    centroids = {}
    for c in set(flatten(grid)):
        if c == 0: continue
        color_cells = [(r, co) for r in range(len(grid)) for co in range(len(grid[0])) if grid[r][co] == c]
        if color_cells:
            centroids[c] = (sum(r for r, co in color_cells) / len(color_cells), 
                           sum(co for r, co in color_cells) / len(color_cells))
    return centroids

